const lockPoll = `-- name: LockPoll :one
SELECT id FROM polls WHERE id = $1::uuid FOR UPDATE
`

// LockPoll locks the poll, local or remote, until the transaction ends, so that the votes in it
// are checked and counted one transaction at a time.
func (q *Queries) LockPoll(ctx context.Context, pollID string) (string, error) {
	row := q.db.QueryRow(ctx, lockPoll, pollID)
	var id string
	err := row.Scan(&id)
	return id, err
}

const lockRemoteMediaCache = `-- name: LockRemoteMediaCache :one
SELECT url, blob_key, content_type, file_size, fetched_at, expires_at, last_accessed_at
FROM remote_media_cache WHERE url = $1 FOR UPDATE
`

// LockRemoteMediaCache reads the entry of @url in a transaction that replaces it, holding the
// row until the transaction ends, so that a concurrent refresh of the URL waits and reads the
// entry this one writes.
func (q *Queries) LockRemoteMediaCache(ctx context.Context, url string) (RemoteMediaCache, error) {
	row := q.db.QueryRow(ctx, lockRemoteMediaCache, url)
	var i RemoteMediaCache
	err := row.Scan(
		&i.Url,
		&i.BlobKey,
		&i.ContentType,
		&i.FileSize,
		&i.FetchedAt,
		&i.ExpiresAt,
		&i.LastAccessedAt,
	)
	return i, err
}

const sumRemoteMediaCacheSize = `-- name: SumRemoteMediaCacheSize :one
SELECT CAST(COALESCE(SUM(file_size), 0) AS BIGINT) FROM remote_media_cache
`

func (q *Queries) SumRemoteMediaCacheSize(ctx context.Context) (int64, error) {
	row := q.db.QueryRow(ctx, sumRemoteMediaCacheSize)
	var column_1 int64
	err := row.Scan(&column_1)
	return column_1, err
}

const touchRemoteMediaCache = `-- name: TouchRemoteMediaCache :exec
UPDATE remote_media_cache SET last_accessed_at = $1 WHERE url = $2
`

type TouchRemoteMediaCacheParams struct {
	LastAccessedAt time.Time
	Url            string
}

func (q *Queries) TouchRemoteMediaCache(ctx context.Context, arg TouchRemoteMediaCacheParams) error {
	_, err := q.db.Exec(ctx, touchRemoteMediaCache, arg.LastAccessedAt, arg.Url)
	return err
}

const upsertRemoteMediaCache = `-- name: UpsertRemoteMediaCache :exec
INSERT INTO remote_media_cache (url, blob_key, content_type, file_size, fetched_at, expires_at, last_accessed_at)
VALUES ($1, $2, $3, $4, $5, $6, $7)
ON CONFLICT (url) DO UPDATE SET
  blob_key = excluded.blob_key,
  content_type = excluded.content_type,
  file_size = excluded.file_size,
  fetched_at = excluded.fetched_at,
  expires_at = excluded.expires_at,
  last_accessed_at = excluded.last_accessed_at
`

type UpsertRemoteMediaCacheParams struct {
	Url            string
	BlobKey        string
	ContentType    string
	FileSize       int64
	FetchedAt      time.Time
	ExpiresAt      time.Time
	LastAccessedAt time.Time
}

func (q *Queries) UpsertRemoteMediaCache(ctx context.Context, arg UpsertRemoteMediaCacheParams) error {
	_, err := q.db.Exec(ctx, upsertRemoteMediaCache,
		arg.Url,
		arg.BlobKey,
		arg.ContentType,
		arg.FileSize,
		arg.FetchedAt,
		arg.ExpiresAt,
		arg.LastAccessedAt,
	)
	return err
}
